function totalMs(stages) {
  return stages.reduce((sum, s) => sum + s.ms, 0);
}

function shareOf(stages, name) {
  const total = stages.reduce((sum, s) => sum + s.ms, 0);
  const stage = stages.find((s) => s.name === name);
  return stage.ms / total;
}

function largestStage(stages) {
  let best = stages[0];
  for (const s of stages) {
    if (s.ms > best.ms) best = s;
  }
  return best.name;
}

function isComplete(stages, measuredTotal) {
  const sum = stages.reduce((total, s) => total + s.ms, 0);
  return sum === measuredTotal;
}

function hasOverlap(stages, measuredTotal) {
  const sum = stages.reduce((total, s) => total + s.ms, 0);
  return sum > measuredTotal;
}

function unaccountedMs(stages, measuredTotal) {
  const sum = stages.reduce((total, s) => total + s.ms, 0);
  return measuredTotal - sum;
}

function smallestStage(stages) {
  let best = stages[0];
  for (const s of stages) {
    if (s.ms < best.ms) best = s;
  }
  return best.name;
}

function audit(stages, measuredTotal) {
  const sum = stages.reduce((total, s) => total + s.ms, 0);
  if (sum === measuredTotal) return "complete";
  return sum < measuredTotal ? "missing" : "overlap";
}

function auditReport(stages, measuredTotal) {
  const sum = stages.reduce((total, s) => total + s.ms, 0);
  const gapMs = measuredTotal - sum;
  const status = gapMs === 0 ? "complete" : gapMs > 0 ? "missing" : "overlap";
  return { status, gapMs };
}

function dominantStage(stages, threshold) {
  const total = stages.reduce((sum, s) => sum + s.ms, 0);
  for (const s of stages) {
    if (s.ms / total >= threshold) return s.name;
  }
  return null;
}

function largestAfterFix(stages, name, newMs) {
  const after = stages.map((s) => (s.name === name ? { name: s.name, ms: newMs } : s));
  let best = after[0];
  for (const s of after) {
    if (s.ms > best.ms) best = s;
  }
  return best.name;
}
